import React, { useCallback, useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomSwitch,
  Loading,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import clustersApi from "../../../api/clustersApi";
import CustomTextArea from "../../../components/forms/CustomTextArea";
import { Modal } from "antd";
import transportApi from "../../../api/transport/transportApi";
import rolesApi from "../../../api/rolesApi";

export default function SaccoRoleFormModal({
  ismodalOpen,
  setisModalOpen,
  role,
  modalTitle = "Add new inventory role",
  updated,
  setUpdated,
}) {
  const [clusters, setclusters] = useState([]);
  const getClustersApi = useApi(clustersApi.clustersAction);
  const getClusters = useCallback(async () => {
    await getClustersApi.request({
      action: "GetClusters",
    });
  }, []);

  useEffect(() => {
    if (getClustersApi.data && getClustersApi.data.length) {
      setclusters(
        getClustersApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    if (
      getClustersApi.data &&
      getClustersApi.data.response_message &&
      getClustersApi.data.response_code === 1
    ) {
      toast.error(getClustersApi.data.response_message);
    }

    if (
      getClustersApi.data &&
      getClustersApi.data.response_message &&
      getClustersApi.data.response_code === 0
    ) {
      toast.success(getClustersApi.data.response_message);
    }

    console.log("getClustersApi.data", getClustersApi.data);
  }, [getClustersApi.data]);

  useEffect(() => {
    getClusters();
  }, []);

  const roleActionsApi = useApi(rolesApi.rolesAction);

  const [errors, setErrors] = useState();

  const handleVehicleAction = async (data) => {
    console.log("data at", data);
    const result = await roleActionsApi.request(data);

    if (result.ok) {
      console.log("res", result);
      setUpdated(true);
      setisModalOpen(false);
    } else {
      setUpdated(false);
    }
  };

  useEffect(() => {}, [role]);

  useEffect(() => {
    if (roleActionsApi.data) {
      setisModalOpen(false);
      // if (transportActionsApi.data.destination) {
      //     setDestination(transportActionsApi.data.destination)
      // }

      if (roleActionsApi.data.errors) {
        setErrors(roleActionsApi.data.errors);
      }
    }

    console.log("roleActionsApi.data", roleActionsApi.data);
  }, [roleActionsApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const formik = useFormik({
    initialValues: {
      cluster: role ? { label: role.cluster_title, value: role.cluster } : "",
      title: role ? role.title : "",
      description: role ? role.description : "",
    },

    validationSchema: Yup.object({
      title: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Title is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      if (role) {
        handleVehicleAction({
          action: "UpdateRole",
          role_details: {
            id: role.id,
            cluster: values.cluster.value,
            description: values.description,
            title: values.title,
          },
        });
      } else {
        handleVehicleAction({
          action: "CreateRole",
          role_details: {
            cluster: values.cluster.value,
            description: values.description,
            title: values.title,
          },
        });
      }

      // resetForm();
    },
  });

  //Status switch
  const [switchLabel, setswitchLabel] = useState("Activate");
  const handleSwitchChange = (checked) => {
    console.log("Swict", checked);
    formik.setFieldValue("is_active", checked ? "true" : "false");
    setswitchLabel(checked ? "Deactivate" : "Activate");

    // console.log('eee', e.target.checked)
  };

  //All crew  switch
  const [switchAllCrewLabel, setswitchAllCrewLabel] = useState("No");
  const handleAllCrewSwitchChange = (checked) => {
    formik.setFieldValue("per_crew", checked ? "true" : "false");
    setswitchAllCrewLabel(checked ? "No" : "Yes");

    // console.log('eee', e.target.checked)
  };

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  return (
    <div className="w-full">
      <Modal
        width={540}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
          >
            <CustomInput
              required={true}
              id="title"
              name="title"
              onChange={formik.handleChange}
              placeholder="Enter role title"
              size="large"
              type="text"
              value={formik.values.title}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.cluster}
            error={formik.errors.cluster}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="cluster"
              id="cluster"
              label="Select cluster"
              size="large"
              onChange={(value) => formik.setFieldValue("cluster", value)}
              value={formik.values.cluster}
              placeholder="Select cluster"
              options={clusters}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.description}
            error={formik.errors.description}
          >
            <CustomTextArea
              required={true}
              id="description"
              name="description"
              onChange={formik.handleChange}
              placeholder="Enter short description of the subscription"
              size="large"
              type="text"
              rows={2}
              value={formik.values.description}
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
