import React, { useCallback, useEffect, useRef, useState } from "react";
import SaccoRolesTable from "./SaccoRolesTable";

import useApi from "../../../hooks/useApi";
import { useNavigate } from "react-router-dom";
import rolesApi from "../../../api/rolesApi";
import { ToastContainer, toast } from "react-toastify";
import SaccoRoleFormModal from "./SaccoRoleFormModal";
import { usePageVisibility } from "../../../hooks/userPageVisibility";

const columns = [
  { name: "Title", uid: "title" },
  { name: "Cluster", uid: "cluster_title" },
  { name: "Description", uid: "description" },
  { name: "Date Created", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function SaccoRolesList() {
  const [ismodalOpen, setisModalOpen] = useState(false);

  const navigate = useNavigate();
  const [role, setRole] = useState();
  const [roles, setRoles] = useState([]);
  const [data, setdata] = useState([]);
  const [updated, setUpdated] = useState(false);
  const [modalTitle, setmodalTitle] = useState("");
  const getRolesApi = useApi(rolesApi.rolesAction);
  const [user, setUser] = useState();
  const [selectedDates, setSelectedDates] = useState();

  const getSaccoSubscriptions = useCallback(async () => {
    await getRolesApi.request({
      action: "GetEntityRoles",
    });
  }, []);

  useEffect(() => {
    if (getRolesApi.data && getRolesApi.data.length) {
      setRoles(getRolesApi.data);
    }

    if (
      getRolesApi.data &&
      getRolesApi.data.response_message &&
      getRolesApi.data.response_code === 1
    ) {
      toast.error(getRolesApi.data.response_message);
    }

    if (
      getRolesApi.data &&
      getRolesApi.data.response_message &&
      getRolesApi.data.response_code === 0
    ) {
      toast.success(getRolesApi.data.response_message);
    }

    console.log("getRolesApi.data", getRolesApi.data);
  }, [getRolesApi.data]);

  useEffect(() => {
    setdata(roles);
  }, [roles]);

  const handleFilter = (e) => {
    const search_param = e;

    if (roles && roles.length > 0 && search_param && search_param !== "") {
      setdata(
        roles.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(roles);
    }
  };

  useEffect(() => {
    getSaccoSubscriptions();
  }, []);

  useEffect(() => {
    getSaccoSubscriptions();
  }, [updated]);

  const handleEditAction = (item) => {
    setisModalOpen(true);
    setRole(item);
    setmodalTitle(`Edit ${item.title}`);
    setUpdated(false);
  };

  const handleAddAction = () => {
    setisModalOpen(true);
    setmodalTitle("Add new role");
    setRole(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/routes/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/routes/delete/${item.id}`);
  };

  useEffect(() => {
    if (user) {
      getSaccoSubscriptions(user);
    }
  }, [updated, user]);

  const isPageVisible = usePageVisibility();
  const timerIdRef = useRef(null);
  const [isPollingEnabled, setIsPollingEnabled] = useState(true);

  useEffect(() => {
    const pollingCallback = () => {
      // Your polling logic here
      getSaccoSubscriptions();

      // Simulating an API failure in the polling callback
      //   const shouldFail = Math.random() < 0.2; // Simulate 20% chance of API failure

      //   if (shouldFail) {
      //     setIsPollingEnabled(false);
      //     console.log("Polling failed. Stopped polling.");
      //   }
    };

    const startPolling = () => {
      // pollingCallback(); // To immediately start fetching data
      // Polling every 30 seconds
      timerIdRef.current = setInterval(pollingCallback, 30000);
    };

    const stopPolling = () => {
      clearInterval(timerIdRef.current);
    };

    if (isPageVisible && isPollingEnabled) {
      startPolling();
    } else {
      stopPolling();
    }

    return () => {
      stopPolling();
    };
  }, [isPageVisible, isPollingEnabled, getSaccoSubscriptions]);

  return (
    <div>
      <ToastContainer position="bottom-center" theme="colored" />
      {ismodalOpen && (
        <SaccoRoleFormModal
          ismodalOpen={ismodalOpen}
          setisModalOpen={setisModalOpen}
          role={role}
          modalTitle={modalTitle}
          updated={updated}
          setUpdated={setUpdated}
        />
      )}
      <SaccoRolesTable
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
        selectedDates={selectedDates}
        setSelectedDates={setSelectedDates}
      />
    </div>
  );
}

export default SaccoRolesList;
